def minimumSum(nums1, nums2):
    # First index of every value in nums1
    first1 = {}
    for i, v in enumerate(nums1):
        if v not in first1:
            first1[v] = i

    best = float('inf')
    for j, v in enumerate(nums2):
        if v in first1:
            best = min(best, first1[v] + j)
    return best if best != float('inf') else -1
